local x=np.transpose(np.astype(np.arange(0,"int64"):reshape({2,0,3}),"int32"),{3,2,1})
local before=x:tolist()
local y=r:permuted(x,nil,x)
deep(y.dtype,"int32","1/(2, 0, 3)/int32/transpose/None/out_same dtype")
deep(y:tolist(),{{},{},{}},"1/(2, 0, 3)/int32/transpose/None/out_same values")
deep(x:tolist(),{{},{},{}},"1/(2, 0, 3)/int32/transpose/None/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"8306bdf37922e4ff","1/(2, 0, 3)/int32/transpose/None/out_same pcg")
cases=cases+1; end
